// Extrai a mensagem do payload (suporta múltiplos formatos)
const body = $input.item.json.body || $input.item.json;

let chatInput = '';

// Formato 1: OpenAI messages array
if (body.messages && Array.isArray(body.messages)) {
  // Pega a última mensagem do usuário
  const userMessages = body.messages.filter(m => m.role === 'user');
  if (userMessages.length > 0) {
    chatInput = userMessages[userMessages.length - 1].content;
  }
}
// Formato 2: campo chatInput direto
else if (body.chatInput) {
  chatInput = body.chatInput;
}
// Formato 3: campo message
else if (body.message) {
  chatInput = body.message;
}
// Formato 4: campo content
else if (body.content) {
  chatInput = body.content;
}

if (!chatInput) {
  throw new Error('No message found in payload. Send either: {"messages":[{"role":"user","content":"..."}]} or {"chatInput":"..."} or {"message":"..."}');
}

// Retorna no formato esperado pelo AI Agent
return {
  chatInput: chatInput,
  // Preserva outros campos úteis
  model: body.model,
  stream: body.stream,
  temperature: body.temperature,
  max_tokens: body.max_tokens
};
